package com.santhosh.dashboard.service; import com.santhosh.dashboard.model.SecurityEvent; import com.santhosh.dashboard.repository.SecurityEventRepository; import org.springframework.stereotype.Service; import java.io.*; import java.net.InetAddress; import java.nio.charset.StandardCharsets; import java.time.LocalDateTime; import java.util.*; import java.util.regex.*;
@Service public class WindowsEventLogService { private final SecurityEventRepository repo; public WindowsEventLogService(SecurityEventRepository repo){this.repo=repo;} public Map<String,Object> collect(int count){ if(!System.getProperty("os.name","").toLowerCase().contains("win")) return Map.of("status","Data unavailable","message","Windows Event Log is available only on Windows"); try{ Process p=new ProcessBuilder("wevtutil","qe","Security","/c:"+Math.min(Math.max(count,1),100),"/rd:true","/f:xml").redirectErrorStream(true).start(); String out=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8); int exit=p.waitFor(); if(exit!=0) return Map.of("status","Data unavailable","message","Windows Event Log permission or query failed"); String host; try{host=InetAddress.getLocalHost().getHostName();}catch(Exception e){host="Data unavailable";} int imported=0; Matcher m=Pattern.compile("<EventID[^>]*>(\\d+)</EventID>.*?<Level>(\\d+)</Level>",Pattern.DOTALL).matcher(out); while(m.find() && imported<100){ repo.save(new SecurityEvent(LocalDateTime.now(),"Windows Event Log",m.group(1),host,"INFO","Windows Security event collected","SECURITY","Level="+m.group(2))); imported++; } return Map.of("status","OK","imported",imported); }catch(Exception e){return Map.of("status","Data unavailable","message","Windows Event Log integration failed safely");} } }
